#!/usr/bin/env node

import { parseCommandLine } from './lib/cli/argParser.mjs';
import { convertMarkdownPair } from './lib/markdown/index.mjs';

const parseResult = parseCommandLine(process.argv.slice(2), process.argv[1]);

if (parseResult.kind === 'help') {
  process.stdout.write(`${parseResult.text}\n`);
  process.exit(0);
}

if (parseResult.kind === 'error') {
  process.stderr.write(`${parseResult.text}\n`);
  process.exit(parseResult.exitCode);
}

const conversionResult = convertMarkdownPair(parseResult.values.a, parseResult.values.b);

if (conversionResult.status !== 0) {
  if (conversionResult.stderr.length > 0) {
    process.stderr.write(conversionResult.stderr);
  }

  process.exit(conversionResult.status);
}

process.stdout.write(conversionResult.stdout);

