import { buildError, buildHelp, getProgramName } from './messages.mjs';

function isOptionToken(token) {
  return typeof token === 'string' && token.length > 1 && token[0] === '-';
}

function buildMissingMessage(missing) {
  return `the following arguments are required: ${missing.join(', ')}`;
}

function buildUnknownMessage(tokens) {
  return `unrecognized arguments: ${tokens.join(' ')}`;
}

export function parseCommandLine(argv, scriptPath) {
  const programName = getProgramName(scriptPath);

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        text: buildHelp(programName),
      };
    }
  }

  const values = {
    a: undefined,
    b: undefined,
  };

  const extras = [];

  for (let index = 0; index < argv.length; ) {
    const token = argv[index];

    if (token === '--a' || token === '--b') {
      const next = argv[index + 1];

      if (next === undefined || isOptionToken(next)) {
        return {
          kind: 'error',
          exitCode: 2,
          text: buildError(programName, `argument ${token}: expected one argument`),
        };
      }

      values[token.slice(2)] = next;
      index += 2;
      continue;
    }

    if (token.startsWith('--a=')) {
      values.a = token.slice(4);
      index += 1;
      continue;
    }

    if (token.startsWith('--b=')) {
      values.b = token.slice(4);
      index += 1;
      continue;
    }

    if (isOptionToken(token)) {
      extras.push(token);

      const next = argv[index + 1];
      if (next !== undefined && !isOptionToken(next)) {
        extras.push(next);
        index += 2;
      } else {
        index += 1;
      }

      continue;
    }

    extras.push(token);
    index += 1;
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      text: buildError(programName, buildUnknownMessage(extras)),
    };
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      text: buildError(programName, buildMissingMessage(missing)),
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

