import { spawnSync } from 'node:child_process';

const EXECUTABLE_PATH = '/workspace/dataset/test6_executable';

function buildExecutableArgs(a, b) {
  return [`--a=${a}`, `--b=${b}`];
}

export function runMarkdownExecutable(a, b) {
  const result = spawnSync(EXECUTABLE_PATH, buildExecutableArgs(a, b), {
    encoding: 'utf8',
  });

  if (result.error) {
    throw result.error;
  }

  return {
    status: result.status === null ? 1 : result.status,
    stdout: result.stdout || '',
    stderr: result.stderr || '',
  };
}

